    if (T == 0) {
        /* 1 rei e N-1 peoes: N posicoes possiveis para o rei */
        ans = N;
    } else if (T == 1) {
        /* 1 rei e 1 torre: N*(N-1) arranjos distintos */
        ans = N * (N - 1);
    } else {
        /* 1 rei entre 2 torres: soma_{i=2}^{N-1} (i-1)*(N-i) = C(N,3) */
